SELECT k.name || ' — вид объявлен обязательным (' || coalesce(k.spec->>'required-why','') || '), документа нет, и план о нём молчит' AS detail FROM kind_layout k WHERE (k.spec->>'required')::boolean IS TRUE AND NOT EXISTS (SELECT 1 FROM project_documents d WHERE d.project_id = $1 AND d.entity_kind = k.name) AND NOT EXISTS (SELECT 1 FROM project_document_plan p WHERE p.project_id = $1 AND p.planned_kind = k.name AND trim(regexp_replace(p.state_text, '^[^:]*:?', '')) <> '') AND true ORDER BY 1
